def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def git(*a):return subprocess.check_output(['git',*a],text=True).strip()
def require(v,m):
 if not v:raise SystemExit(m)
c=json.loads((E/'closure.json').read_text())
require(c['all_passed'] is True and all(sha(p)==v for p,v in c['sha256'].items()),'Closure failure/drift')
require(not git('diff','--cached','--name-only'),'Prior stage')
selfname=str((E/'publication.json').relative_to(R));tracked={'diagnostics/simplex-core-architecture/STATUS.md','docs/superpowers/plans/2026-10-11-simplex-core-architecture.md'}
require(NAMES==json.loads((E/'publication-names.json').read_text()) and len(NAMES)==len(set(NAMES)),'Fixed names')
require(set(git('ls-files','--others','--exclude-standard').splitlines())==(set(NAMES)-tracked-{selfname})|{'Manifest.toml','LocalPreferences.toml'},'Untracked scope')
require(set(git('diff','--name-only','HEAD').splitlines())==tracked,'Tracked scope')
other=[n for n in NAMES if n!=selfname]
o=dict(all_passed=True,scope='Accepted local MA-V guard qualification only; complete DenseLU qualification and production promotion remain open',exact_names=NAMES,sha256={str(R/n):sha(R/n) for n in other},git_blobs={n:git('hash-object','--',n) for n in other})
with (E/'publication.json').open('x') as f:json.dump(o,f,indent=2);f.write('\n')
subprocess.run(['git','add','--',*NAMES],check=True)
require(set(git('diff','--cached','--name-only').splitlines())==set(NAMES),'Staged names')
for n in NAMES:require(git('rev-parse',':'+n)==git('hash-object','--',n),'Staged blob '+n)
r=subprocess.run(['git','diff','--cached','--check'],capture_output=True,text=True)
require(r.returncode==0 and not r.stdout and not r.stderr,'Staged diff check: '+r.stdout+r.stderr)
print(json.dumps(dict(exact_staged_names_blobs=len(NAMES),listed_hashes=len(other),authored_diff_clean=True)))
